#!/usr/bin/env python3
"""Rebuild the affected groups twice and verify generated bytes and isolation.

No catalogue is required. Only Atelier and Foundry generators are invoked.
The result is structural/determinism evidence, not independent visual approval.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[1]
LIBRARIES = ('atelier', 'foundry')
PROTECTED = ('client/Assets', 'tools/art', 'content_src', 'content')


def fingerprint(folders, ignore_elapsed=False):
    files = {}
    for folder in folders:
        for path in sorted((ROOT / folder).rglob('*')):
            if not path.is_file() or '__pycache__' in path.parts:
                continue
            data = path.read_bytes()
            if ignore_elapsed and path.name == 'coverage.json':
                value = json.loads(data)
                value.pop('built_seconds', None)
                data = json.dumps(value, sort_keys=True, separators=(',', ':')).encode()
            files[path.relative_to(ROOT).as_posix()] = hashlib.sha256(data).hexdigest()
    return files


def command(*args):
    subprocess.run([sys.executable, *args], cwd=ROOT, check=True,
                   env={**os.environ, 'PYTHONDONTWRITEBYTECODE': '1'})


def rebuild():
    command('atelier/build.py', '--only', 'terrain', '--jobs', '2')
    command('atelier/build.py', '--manifest')
    atelier_before = fingerprint(('atelier',))
    command('foundry/build.py', '--only', 'ground', 'ui', '--jobs', '2')
    command('foundry/build.py', '--atlas')
    command('foundry/build.py', '--pack-atelier', '--atlas')
    for sheet in ('ground', 'scene', 'ui', 'cliffs', 'panels', 'terrain'):
        command('foundry/preview.py', sheet)
    if atelier_before != fingerprint(('atelier',)):
        raise AssertionError('Foundry wrote into Atelier.')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--report')
    args = parser.parse_args()
    protected = fingerprint(PROTECTED)
    command('-m', 'unittest', 'discover', '-s', 'foundry/tests', '-v')
    rebuild()
    first = fingerprint(LIBRARIES, ignore_elapsed=True)
    rebuild()
    second = fingerprint(LIBRARIES, ignore_elapsed=True)
    difference = [name for name in sorted(first.keys() | second.keys()) if first.get(name) != second.get(name)]
    if difference:
        raise AssertionError('Nondeterministic files: ' + ', '.join(difference))
    if protected != fingerprint(PROTECTED):
        raise AssertionError('A protected game directory changed.')
    from PIL import __version__ as pillow_version
    report = {'result': 'pass', 'python': sys.version.split()[0], 'pillow': pillow_version,
              'compared_files': len(second), 'compared_pngs': sum(name.endswith('.png') for name in second),
              'allowed_difference': 'built_seconds in coverage.json only',
              'foundry_did_not_write_atelier': True, 'protected_directories_unchanged': True,
              'sha256': second}
    if args.report:
        target = Path(args.report)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    print(json.dumps({key: value for key, value in report.items() if key != 'sha256'}, indent=2))


if __name__ == '__main__':
    main()
